-- Stage 13b: seed the demo storefront catalogue.
--
-- Deterministic, idempotent demo data for the customer storefront:
--   724 products, 154 brands,
--   1703 variants, 2534 image rows,
--   2092 price rows, 1703 inventory rows.
--
-- Idempotency: brands/products/variants use ON CONFLICT DO NOTHING.
-- Images, prices and inventory are deleted (scoped to the demo SKU
-- prefix YS-DEMO-2026%) and re-inserted, so re-running converges.
-- prices.created_by resolves to the stage 13a owner auth user.
-- A single demo warehouse location is created if missing.
--
-- No schema changes and no category-tree changes are made here.

set search_path = public, extensions;

-- ---------------------------------------------------------------------
-- Temporary lookup helpers (dropped at the end of this migration)
-- ---------------------------------------------------------------------
create or replace function app.demo_owner_id()
returns uuid
language sql stable
as $$
  select id from auth.users where email = 'owner@yemanuelstore.com' limit 1;
$$;

create or replace function app.demo_location_id()
returns uuid
language sql stable
as $$
  select id from public.locations where code = 'YS-DEMO-2026-ACC' limit 1;
$$;

create or replace function app.demo_category_id(p_slug text)
returns uuid
language sql stable
as $$
  select id from public.categories where slug = p_slug limit 1;
$$;

create or replace function app.demo_brand_id(p_slug text)
returns uuid
language sql stable
as $$
  select id from public.brands where slug = p_slug limit 1;
$$;

create or replace function app.demo_product_id(p_slug text)
returns uuid
language sql stable
as $$
  select id from public.products where slug = p_slug limit 1;
$$;

create or replace function app.demo_variant_id(p_sku text)
returns uuid
language sql stable
as $$
  select id from public.product_variants where sku = p_sku limit 1;
$$;

-- ---------------------------------------------------------------------
-- 1. Demo warehouse location (idempotent)
-- ---------------------------------------------------------------------
insert into public.locations (code, name, location_type, region_id, city, address_line_1, address_line_2, phone, status)
select
  'YS-DEMO-2026-ACC',
  'Accra Demo Warehouse',
  'warehouse'::public.location_type,
  r.id,
  'Accra',
  'Demo Distribution Hub, Tema Motorway',
  'Km 12, Spintex Road',
  '+233 24 000 0000',
  'active'::public.entity_status
from public.regions r
where r.code = 'ACC'
on conflict (code) do nothing;

