-- ---------------------------------------------------------------------
-- 3. Remove any previously-seeded demo catalogue rows (idempotency)
-- ---------------------------------------------------------------------
delete from public.inventory_items
where variant_id in (
  select id from public.product_variants where sku like 'YS-DEMO-2026%'
);

delete from public.products
where id in (
  select product_id from public.product_variants where sku like 'YS-DEMO-2026%'
);

